{"name":"i915_pm_suspend","qualified_name":"workspace-linux.drivers.gpu.drm.i915.i915_driver.i915_pm_suspend","label":"Function","file_path":"/workspace/linux/drivers/gpu/drm/i915/i915_driver.c","start_line":1392,"end_line":1405,"source":"static int i915_pm_suspend(struct device *kdev)
{
	struct drm_i915_private *i915 = kdev_to_i915(kdev);

	if (!i915) {
		dev_err(kdev, "DRM not initialized, aborting suspend.\n");
		return -ENODEV;
	}

	if (i915->drm.switch_power_state == DRM_SWITCH_POWER_OFF)
		return 0;

	return i915_drm_suspend(&i915->drm);
}
